function serveAsset(res, name){const a=EMBEDDED_ASSETS[name];if(!a)return false;res.set('Content-Type',a.type);res.set('Cache-Control','no-cache');res.send(Buffer.from(a.b64,'base64'));return true;}
app.get('/', (_req,res)=>serveAsset(res,'index.html'));
